SIGNAL SAL: STD_LOGIC_VECTOR(639 DOWNTO 0);
SIGNAL PIX: STD_LOGIC;
SIGNAL COLOR: INTEGER RANGE 0 TO 2;
SIGNAL CLK2: STD_LOGIC;
SIGNAL CONTA: INTEGER RANGE 0 TO 21;
SIGNAL AUX2: INTEGER RANGE 0 TO 1249999;
SIGNAL CLK_ASM : STD_LOGIC;
SIGNAL VICTORY : STD_LOGIC;

SIGNAL X1: INTEGER RANGE 0 TO 640 := 280;
SIGNAL X2: INTEGER RANGE 0 TO 640 := 320; 
SIGNAL Y1: INTEGER RANGE 0 TO 480 := 200; 
SIGNAL Y2: INTEGER RANGE 0 TO 480 := 240;

SIGNAL X3: INTEGER RANGE 0 TO 640 := 290;
SIGNAL X4: INTEGER RANGE 0 TO 640 := 310; 
SIGNAL Y3: INTEGER RANGE 0 TO 480 := 180; 
SIGNAL Y4: INTEGER RANGE 0 TO 480 := 200; 

------------------------ CARTA ASM PARA CONTADOR -------------------------
TYPE EDOS IS (INICIO, IZQ, DER, ARR, ABA, RETARDO);
SIGNAL PRES: EDOS := INICIO;
SIGNAL RET: INTEGER RANGE 0 TO 100000 := 0;
SIGNAL AUX: INTEGER RANGE 0 TO 50;

SIGNAL DRAW1, DRAW2:STD_LOGIC;

BEGIN

	PROCESS(CLK_ASM, U, D, L, RR, DRAW1, DRAW2)
	BEGIN
		IF RISING_EDGE(CLK) THEN
			CASE PRES IS
				WHEN INICIO => IF DRAW1 = '1' AND DRAW2 = '1' THEN
						X1 <= 280; X2 <= 320;
						Y1 <= 200; Y2 <= 240;
						X3 <= 290; X4 <= 310;
						Y3 <= 180; Y4 <= 200;
						PRES <= INICIO;
							ELSIF U = '0' THEN
						PRES <= ARR;
							ELSIF D = '0' THEN
						PRES <= ABA;
							ELSIF L = '0' THEN
						PRES <= IZQ;
							ELSIF RR = '0' THEN
						PRES <= DER;
							ELSE
						PRES <= INICIO;
							END IF;
										
				WHEN DER => X1 <= X1 + 1; X2 <= X2 + 1;
						X3 <= X3 + 1; X4 <= X4 + 1;
						PRES <= RETARDO;
								
				WHEN IZQ => X1 <= X1 - 1; X2 <= X2 - 1;
							X3 <= X3 - 1; X4 <= X4 - 1;
						PRES <= RETARDO;		
							
				WHEN ARR => Y1 <= Y1 + 1; Y2 <= Y2 + 1;
					Y3 <= Y3 + 1; Y4 <= Y4 + 1;
					PRES <= RETARDO;
					
				WHEN ABA => Y1 <= Y1 - 1; Y2 <= Y2 - 1;
						Y3 <= Y3 - 1; Y4 <= Y4 - 1;
						PRES <= RETARDO;
								
				WHEN RETARDO => IF RET = 119999 THEN
							RET <= 0;
							PRES <= INICIO;
						ELSE
							RET <= RET + 1;
						END IF;
			END CASE;
	    END IF;
	END PROCESS;

    PROCESS(CLK, RST2, HPOS, VPOS, VIDEO) -- PROCESO PARA COLOREAR LOS PIXELES
    BEGIN
		IF RST2 = '1' THEN
            COLOR <= 2;
      	ELSIF FALLING_EDGE(CLK) THEN
			IF VICTORY = '0' THEN
				IF VIDEO = '1' THEN -- dibujado de figura
					IF (HPOS >= X1 AND HPOS <= X2) AND (VPOS >= Y1 AND VPOS <= Y2) THEN
								R <= "1111";
								G <= "0000";
								B <= "0000";
								DRAW1 <= '1';
					ELSIF (HPOS >= X3 AND HPOS <= X4) AND (VPOS >= Y3 AND VPOS <= Y4) THEN
								R <= "1111";
								G <= "0000";
								B <= "0000";
								DRAW1 <= '1';
					ELSIF (HPOS >= 0 AND HPOS <= 639) AND (VPOS >= 0 AND VPOS <= 479) THEN
						SAL <= ROM1(VPOS);
						PIX <= SAL(HPOS);
					END IF;
				END IF;
			ELSE
				IF VIDEO = '1' THEN
					IF (HPOS >= 0 AND HPOS <= 639) AND (VPOS >= 0 AND VPOS <= 479) THEN
						IF CONTA = 1 THEN
							SAL <= ROM2(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 2 THEN
							SAL <= ROM3(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 3 THEN
							SAL <= ROM4(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 4 THEN
							SAL <= ROM5(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 5 THEN
							SAL <= ROM6(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 6 THEN
							SAL <= ROM7(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 7 THEN
							SAL <= ROM8(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 8 THEN
							SAL <= ROM9(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 9 THEN
							SAL <= ROM10(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 10 THEN
							SAL <= ROM11(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 11 THEN
							SAL <= ROM12(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 12 THEN
							SAL <= ROM13(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 13 THEN
							SAL <= ROM14(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 14 THEN
							SAL <= ROM15(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 15 THEN
							SAL <= ROM16(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 16 THEN
							SAL <= ROM17(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 17 THEN
							SAL <= ROM18(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 18 THEN
							SAL <= ROM19(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 19 THEN
							SAL <= ROM20(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 20 THEN
							SAL <= ROM21(VPOS);
							PIX <= SAL(HPOS);
						END IF;	
						IF PIX = '0' THEN
							COLOR <= 0;
						ELSE
							COLOR <= 1;
							DRAW2 <= '1';
						END IF;
					ELSE
					  COLOR <= 2;
					END IF;
				END IF;
            END IF;
        END IF;
	END PROCESS;


    PROCESS(CLK)
    BEGIN
        IF RISING_EDGE(CLK) THEN
            IF AUX2 = 0 THEN
                CLK2 <= NOT CLK2;
                AUX2 <= 1249999;
            ELSE
                AUX2 <= AUX2 - 1;
            END IF;
        END IF;
    END PROCESS;

    PROCESS(CLK2)
    BEGIN
        IF FALLING_EDGE(CLK2) THEN
            IF CONTA = 20 THEN
                CONTA <= 0;
            ELSE
                CONTA <= CONTA + 1;
            END IF;
        END IF;
    END PROCESS;

    WITH COLOR SELECT
        R <= "0001" WHEN 0,
              "0011" WHEN 1,
              "0000" WHEN OTHERS;
    WITH COLOR SELECT
        B <= "0001" WHEN 0,
              "0011" WHEN 1,
              "0000" WHEN OTHERS;
    WITH COLOR SELECT
        G <= "0001" WHEN 0,
              "0011" WHEN 1,
              "0000" WHEN OTHERS;

END BEAS;
